const uint8_t *ui_font_get_ascii(uint8_t ch)
{
    if (ch < UI_FONT_ASCII_FIRST || ch > UI_FONT_ASCII_LAST) {
        return NULL;
    }
    return s_ascii_font[ch - UI_FONT_ASCII_FIRST];
}
